  DATA.put(CR,rss("Crunchyroll","crunchyroll.com","oldcr"));DATA.put(TR,rss("Trending","anitrendz.net","oldtr"));DATA.put(MAL,rss("MAL","myanimelist.net","oldmal"));DATA.put(TOHO,atom("toho"));DATA.put(ANI,ani("123"));DATA.put(KADO,rdf("kado"));
  JSONObject first=NewsSync.refresh(ctx,true);ok(first.getJSONArray("items").length()==6&&first.getJSONArray("failed").length()==1&&nm.notified==0,"per-source baseline and partial failure");
  DATA.put(AC,rss("Anime Corner","animecorner.me","oldac"));JSONObject recovery=NewsSync.refresh(ctx,true);ok(recovery.getJSONArray("items").length()==7&&nm.notified==0,"recovered feed seeds without history flood");
  DATA.put(CR,rss("Crunchyroll","crunchyroll.com","newcr","oldcr"));JSONObject fresh=NewsSync.refresh(ctx,true);ok(fresh.getJSONArray("items").length()==8&&nm.notified==1,"new item notifies");ok(nm.last.tap.intent.action.equals(NewsSync.ACTION_OPEN)&&nm.last.tap.intent.target==MainActivity.class,"notification opens app feed");ok(nm.last.icon!=null&&nm.last.subText.contains("Kuro.tv")&&nm.last.actions.size()==2&&nm.last.actions.get(0).tap.intent.action.equals(NewsSync.ACTION_OPEN)&&nm.last.actions.get(1).tap.intent.action.equals(Intent.ACTION_VIEW)&&nm.last.style instanceof Notification.BigTextStyle,"branded expandable alert and open-news action");int expectedFlags=Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP;ok((nm.last.tap.intent.flags&expectedFlags)==expectedFlags,"notification retains existing task");
  NewsSync.refresh(ctx,true);ok(nm.notified==1,"duplicate refresh does not notify");DATA.remove(AC);JSONObject offline=NewsSync.refresh(ctx,true);ok(offline.getJSONArray("items").length()==8&&offline.getJSONArray("failed").length()==1,"offline feed retains cache");
  NewsSync.setEnabled(ctx,false);ok(js.getPendingJob(NewsSync.JOB_ID)==null&&!NewsSync.enabled(ctx)&&nm.cancelled>0,"off disables job and clears alert");DATA.put(CR,rss("Crunchyroll","crunchyroll.com","offcr","newcr","oldcr"));int before=count(CR);NewsSync.refreshIfEnabled(ctx);ok(count(CR)==before,"automatic startup/resume does not fetch when off");NewsSync.refresh(ctx,true);ok(nm.notified==1,"manual News works without alerting when off");NewsSync.setEnabled(ctx,true);ok(js.getPendingJob(NewsSync.JOB_ID)!=null,"on reschedules");
  DATA.put(AC,rss("Anime Corner","animecorner.me","oldac"));STATUS.put(AC,403);JSONObject restricted=NewsSync.refresh(ctx,true);ok(restricted.getJSONArray("failed").toString().contains("restricted"),"403 explained");int blockedCount=count(AC);Context.PREFS.get(NewsSync.PREFS).edit().putLong("checkedAt",0).apply();NewsSync.refreshIfEnabled(ctx);ok(count(AC)==blockedCount,"automatic checks stop after 403");STATUS.remove(AC);NewsSync.refresh(ctx,true);ok(count(AC)==blockedCount+1,"explicit Refresh can retry restricted source once");
  String alt="https://cr-news-api-service.prd.crunchyrollsvc.com/v1/en-US/alternate";DATA.put(alt,DATA.get(CR));STATUS.put(CR,301);LOCATION.put(CR,alt);JSONObject redirected=NewsSync.refresh(ctx,true);ok(redirected.getJSONArray("failed").length()==0&&count(alt)>0,"same-publisher HTTPS redirect succeeds");LOCATION.put(CR,"https://attacker.invalid/steal");JSONObject rejected=NewsSync.refresh(ctx,true);ok(rejected.getJSONArray("failed").toString().contains("Crunchyroll")&&count("https://attacker.invalid/steal")==0,"cross-site redirect refused");STATUS.remove(CR);LOCATION.remove(CR);
  nm.getNotificationChannel(NewsSync.CHANNEL).importance=0;NewsSync.schedule(ctx);ok(js.getPendingJob(NewsSync.JOB_ID)==null,"blocked channel cancels schedule");nm.getNotificationChannel(NewsSync.CHANNEL).importance=3;NewsSync.schedule(ctx);
  JobService.finished=new CountDownLatch(1);NewsJobService service=new NewsJobService();ok(service.onStartJob(new JobParameters()),"job runs asynchronously");ok(JobService.finished.await(5,TimeUnit.SECONDS)&&!JobService.retry,"job completes without retry");
  Context.PREFS.get(NewsSync.PREFS).edit().putLong("checkedAt",0).apply();slow=true;JobService.finished=new CountDownLatch(1);NewsJobService stopped=new NewsJobService();JobParameters p=new JobParameters();ok(stopped.onStartJob(p),"stoppable job started");ok(stopped.onStopJob(p),"stopped job eligible for retry");java.lang.reflect.Field f=NewsJobService.class.getDeclaredField("worker");f.setAccessible(true);((Thread)f.get(stopped)).join(2000);ok(JobService.finished.getCount()==1,"stopped job does not finish twice");slow=false;
  java.lang.reflect.Method alert=NewsSync.class.getDeclaredMethod("notifyUpdates",Context.class,List.class);alert.setAccessible(true);NewsParser.Item one=new NewsParser.Item();one.title="A new announcement";one.source="Studio";one.summary="Useful summary";NewsParser.Item two=new NewsParser.Item();two.title="Another story";two.source="Anime News";
  alert.invoke(null,ctx,Arrays.asList(one));ok(nm.last.title.equals(one.title)&&((Notification.BigTextStyle)nm.last.style).text.contains("Useful summary"),"single update shows real summary");
